/* Presentation only; mutations use existing server contracts. */
(function(g){'use strict';const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function render(c){const{view,state,job,jobs,actor,icon}=c,chef=c.mode==='chef_equipe',assignedChef=chef&&state.lead?.assignment?.jobId===job?.id,b=(label,attrs,secondary=true)=>`<button type="button" class="button ${secondary?'secondary':''}" ${attrs}>${label}</button>`,h=(title,sub='')=>`<header class="field-heading"><h1>${title}</h1><p>${esc(sub)}</p></header>`,row=(label,attrs,sub='')=>`<button class="field-row" type="button" ${attrs}><span><strong>${label}</strong>${sub?`<small>${esc(sub)}</small>`:''}</span>${icon('arrow')}</button>`,choose=()=>jobs.length?`<label class="field-job-choice">Chantier<select data-field-job>${jobs.map(j=>`<option value="${esc(j.id)}"${j.id===job?.id?' selected':''}>${esc(j.number||'')} ${esc(j.name)} · ${esc(j.address||'')}</option>`).join('')}</select></label><p class="field-muted">${esc(job?.name||'')}<br>${esc(job?.address||'')}</p>`:'<p>Aucun chantier assigné. Contactez le bureau.</p>';
if(view==='day'){const weather=job?g.MIRToday?.weather(job,entry=>{const target=document.querySelector('[data-field-weather]');if(target?.dataset.fieldWeather===job.id)target.textContent=entry.label;}):null,shift=state.punch?.activeShift,notices=state.notifications?.items||[];return `<section class="field-home"><div class="field-date"><time>${new Intl.DateTimeFormat('fr-CA',{weekday:'long',day:'numeric',month:'long'}).format(new Date())}</time><span data-field-weather="${esc(job?.id||'')}">${esc(weather?.label||'Météo indisponible')}</span></div>${h(`${actor?.name?.includes('@')?'Bonjour':'Bonjour, '+esc((actor?.name||'Équipe').split(' ')[0])}`)}${jobs.length>1?b('Changer de chantier','data-view="jobs"'):''}<article class="field-job-hero"><small>MON CHANTIER · JOB ${esc(job?.number||'—')}</small><h2><button type="button" class="field-job-title" data-view="job">${esc(job?.name||'Votre prochaine affectation')}</button></h2><p>${esc(job?.address||'Votre responsable confirmera votre affectation.')}</p><div class="field-actions">${job?b('Voir le dossier','data-view="job"',false):b('Contacter le bureau','data-field-office')}${job?.address?b('Itinéraire',`data-route-job="${esc(job.id)}"`):''}</div></article><section class="field-punch-summary"><div><strong>${shift?'Au travail':'Pointage non commencé'}</strong><small>${shift?'Depuis '+esc(new Date(shift.started_at).toLocaleTimeString('fr-CA',{hour:'2-digit',minute:'2-digit'})):'L’itinéraire ne déclenche aucun pointage.'}</small></div>${b('Punch','data-view="punch"')}</section>${job?`<div class="field-quick">${row(icon('plan')+'Plans','data-view="plans"')}${row(icon('camera')+'Photo','data-field-request="photo"')}${row(icon('info')+'Problème','data-field-request="issue"')}</div>`:''}<section class="field-section"><div class="field-section-title"><h2>À ne pas manquer</h2>${b('Tout voir','data-view="notifications"')}</div>${notices.slice(0,3).map(n=>row(esc(n.title||'Notification'),`data-notification-open="${esc(n.id)}" data-target-view="${esc(n.route?.view||'notifications')}"`)).join('')||'<p class="field-muted">Aucune nouvelle notification pour votre journée.</p>'}</section>${assignedChef?`<section class="field-section"><h2>Mon équipe</h2><p>${(state.lead?.team||[]).filter(m=>m.status==='present').length} présence(s) confirmée(s) · ${(state.lead?.team||[]).length} membres</p><p class="field-muted">Non confirmé ne signifie pas absent.</p>${row('Équipe et présences','data-view="lead-team"')}${row('Tâches du chantier','data-field-tasks')}${row('Préparer le rapport','data-lead-report')}</section>`:''}${row('Mes chantiers','data-view="jobs"',`${jobs.length} chantier(s) autorisé(s)`)}</section>`;}
if(view==='command')return `<section>${h('Commande','Matériel et pliages, dans le même panier.')}<div class="field-command-entries">${row(icon('box')+'Magasin','data-field-catalogue="material"','Matériel, accessoires et favoris')}${row(icon('fold')+'Banque de pliages','data-field-catalogue="fold"','Choisir un profil et entrer les mesures')}${row(icon('plus')+'Dessiner une moulure','data-field-draw','Une pièce personnelle pour votre commande')}</div>${row('Mon panier','data-field-cart',`${c.cartCount} ligne(s) à confirmer`)}${row('Suivre mes commandes','data-view="orders"','Décisions et livraisons partielles')}${row('Matériel et livraisons','data-view="material"')}</section>`;
if(view==='punch'){const p=state.punch||{},a=p.activeShift;return `<section>${h('Punch','Le serveur confirme chaque pointage.')}${choose()}<article class="field-punch-clock"><small>${a?'AU TRAVAIL':'PRÊT À COMMENCER'}</small><h2>${a?'Journée en cours':'Commencer ma journée'}</h2><p>${a?'Début à '+esc(new Date(a.started_at).toLocaleTimeString('fr-CA',{hour:'2-digit',minute:'2-digit'})):'Le GPS est demandé au moment du pointage seulement.'}</p>${p.enabled&&job?b(a?'Terminer':'Commencer',`data-punch="${a?'out':'in'}" data-job="${esc(a?.segment?.job_id||job.id)}"`,false):'<p>Punch indisponible : contactez le bureau.</p>'}</article>${a?`<div class="field-actions">${b('Changer de job','data-punch-switch')}${b('Déplacement','data-punch-travel')}</div>`:''}<div class="field-section">${row('Mes heures','data-view="punch-hours"')}${row('J’ai oublié de puncher','data-punch-forgot')}${row('Mes heures sont incorrectes','data-punch-forgot')}</div><p class="field-muted">L’itinéraire sert à vous rendre au chantier. Il ne déclenche aucun pointage.</p></section>`;}
if(['more','account'].includes(view))return `<section>${h('Plus','Vos outils et vos suivis.')}<div class="field-list">${row('Mes heures','data-view="punch-hours"','Journées, jobs et corrections')}${row('Banque d’heures','data-view="punch-hours"')}${row('Congés et absences','data-view="absences"')}${row('Dépenses et reçus','data-view="expenses"')}${row('Bris d’outil','data-field-request="tool"')}${row('Mes chantiers et documents','data-view="jobs"')}${assignedChef?row('Équipe et présences','data-view="lead-team"')+row('Rapport de journée','data-lead-report'):''}${row('Aide et contact du bureau','data-field-help')}</div></section>`;
if(view==='jobs')return `<section>${h('Mes chantiers','Seulement vos affectations autorisées.')}<div class="field-job-list">${jobs.map(j=>`<button class="field-job-card" type="button" data-field-open-job="${esc(j.id)}"><small>JOB ${esc(j.number||'—')}</small><h2>${esc(j.name)}</h2><p>${esc(j.address||'Adresse à confirmer')}</p><span>Ouvrir le dossier ${icon('arrow')}</span></button>`).join('')||'<p>Aucune affectation. Contactez le bureau.</p>'}</div></section>`;
if(view==='job'){const d=c.dossier;return `<section class="field-dossier">${b('Retour','data-field-back')}${h('Job '+esc(job?.number||'—')+' · '+esc(job?.name||'Dossier chantier'),job?.address||'')}<div class="field-actions">${job?.address?b('Itinéraire',`data-route-job="${esc(job.id)}"`):''}${b('Écrire à l’Adjointe','data-field-office')}</div>${job?.clientName||job?.phone?`<section class="field-section"><h2>Contacts utiles</h2>${job.clientName?`<p>${esc(job.clientName)}</p>`:''}${job.phone?`<a class="button secondary" href="tel:${esc(job.phone.replace(/[^+0-9]/g,''))}">Appeler le contact du chantier</a>`:''}</section>`:''}<div class="field-job-actions">${b('Ajouter des photos','data-field-request="photo"')}${b('Noter un extra','data-field-request="extra"')}${b('Signaler un problème','data-field-request="issue"')}</div>${c.loading?'<p role="status">Chargement du dossier autorisé…</p>':c.error?`<p role="alert" class="field-error">${esc(c.error)}</p>${b('Réessayer','data-field-reload')}`:d?`<section class="field-section"><h2>Plans et documents</h2>${(d.documents||[]).map(x=>row(esc(x.name||'Document privé'),`data-job-document="${esc(x.object_path||'')}"`)).join('')||'<p>Aucun document publié.</p>'}</section><section class="field-section"><h2>Consignes et tâches</h2>${(d.tasks||[]).map(x=>`<p>${esc(x.title)} · ${x.completed_at?'Terminée':'À faire'}</p>`).join('')||'<p>Aucune consigne communiquée.</p>'}</section><section class="field-section"><h2>Photos, extras et problèmes</h2>${(d.activity||[]).map(x=>`<article class="field-feed"><small>${esc(x.created_at?new Date(x.created_at).toLocaleString('fr-CA'):'')} · ${esc(({open:'Envoyé',in_progress:'Pris en charge',resolved:'Résolu',pending:'À examiner',photo:'Photo',field_issue:'Problème chantier',extra:'Extra'})[x.payload?.status||x.activity_type]||'Activité')}</small><h3>${esc(x.payload?.tool||x.payload?.description||x.payload?.note||({photo:'Photo de chantier',field_issue:'Problème chantier',extra:'Extra'})[x.activity_type]||'Activité')}</h3>${x.payload?.photoPath?b('Ouvrir la photo',`data-internal-photo="${esc(x.payload.photoPath)}"`):''}${x.payload?.response?`<p>Réponse : ${esc(x.payload.response)}</p>`:''}</article>`).join('')||'<p>Aucune activité récente.</p>'}${(d.extras||[]).map(x=>`<article class="field-feed"><h3>${esc(x.description)}</h3><p>${esc(({pending:"À examiner",approved:"Approuvé",refused:"Refusé"})[x.status]||"À vérifier")}</p></article>`).join('')}</section><section class="field-section"><h2>Commandes et livraisons</h2>${row('Voir le suivi','data-view="orders"',`${(d.orders||[]).length} commande(s) liée(s)`)}</section><section class="field-section"><h2>Rapports de journée</h2>${(d.reports||[]).map(x=>`<article class="field-feed"><h3>${esc(x.work_done)}</h3><p>${esc(x.comment||'')}</p>${(x.photo_paths||[]).map(path=>b('Ouvrir la photo du rapport',`data-internal-photo="${esc(path)}"`)).join('')}</article>`).join('')||'<p>Aucun rapport envoyé.</p>'}${assignedChef?b('Préparer le rapport','data-lead-report'):''}</section>${c.issueMarkup||''}`:'<p>Ouvrez une job autorisée pour charger son dossier.</p>'}</section>`;}
return null;}
g.MIRFieldViews=Object.freeze({render});})(window);
